import type { Temporal } from '@js-temporal/polyfill'
import type { AutogeneratedInsertableProjectImage, AutogeneratedProjectImage } from './autogenerated/autogenerated_project_image.d.ts'

export type Point = { x: number, y: number }
export type Stroke = { points: Point[], color: string, line_width: number }

type StrokesField = { strokes: Stroke[] | null }

type UploadedFiles = {
	uploaded_at: Temporal.Instant
	original_object_key: string
	display_object_key: string
	thumbnail_object_key: string
} | {
	uploaded_at: null
	original_object_key: null
	display_object_key: null
	thumbnail_object_key: null
}

type OverriddenKeys = keyof StrokesField | keyof UploadedFiles

declare global {
	type DbInsertableProjectImage = Omit<AutogeneratedInsertableProjectImage, OverriddenKeys> & StrokesField & UploadedFiles
	type DbProjectImage = Omit<AutogeneratedProjectImage, OverriddenKeys> & StrokesField & UploadedFiles
}
